<script setup>
import {computed,onMounted,reactive,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,download,activityNames,registrationNames,statusType} from '../api'
const tab=ref('activities'),activities=ref([]),reviewers=ref([]),rows=ref([]),stats=ref({total:0,pending:0,approved:0,rejected:0}),filterId=ref(null),range=ref([]),opened=ref(false),busy=ref(false),loading=ref(false)
const draft=reactive({activityId:null,title:'',content:'',startTime:'',endTime:'',reviewerId:null,attachmentRequired:false,fields:[]})
const fieldTypes=[{value:'text',label:'单行文本'},{value:'textarea',label:'多行文本'},{value:'select',label:'下拉选择'},{value:'number',label:'数字'},{value:'date',label:'日期'}]
async function load(){loading.value=true;try{[activities.value,reviewers.value]=await Promise.all([api('/activities'),api('/reviewers')]);await query()}finally{loading.value=false}}
function open(a){Object.assign(draft,{activityId:a?.activityId||null,title:a?.title||'',content:a?.content||'',startTime:a?.startTime||'',endTime:a?.endTime||'',reviewerId:a?.reviewerId||null,attachmentRequired:a?.formSchema.attachmentRequired||false,fields:JSON.parse(JSON.stringify(a?.formSchema.fields||[{key:'studentNo',label:'学号',type:'text',required:true,maxLength:32},{key:'reason',label:'报名理由',type:'textarea',required:false,maxLength:500}])).map(f=>({...f,optionsText:(f.options||[]).join('，')}))});opened.value=true}
function addField(){draft.fields.push({key:`field${draft.fields.length+1}`,label:'',type:'text',required:false,maxLength:500,optionsText:''})}
async function save(opType){busy.value=true;try{const fields=draft.fields.map(f=>({key:f.key,label:f.label,type:f.type,required:f.required,maxLength:f.maxLength||500,...(f.type==='select'?{options:f.optionsText.split(/[,，]/).map(s=>s.trim()).filter(Boolean)}:{})}));await api('/activities',{method:'POST',body:{...draft,formSchema:{version:1,attachmentRequired:draft.attachmentRequired,fields},opType}});ElMessage.success(opType==='PUBLISH'?'活动已发布':'草稿已保存');opened.value=false;await load()}catch{}finally{busy.value=false}}
async function operate(a,opType){try{await ElMessageBox.confirm(opType==='DELETE'?'确认删除这项草稿活动？':'确认下线此活动？下线后学生不能继续报名。','操作确认',{type:'warning',confirmButtonText:'确认',cancelButtonText:'取消'})}catch{return}await api('/activities',{method:'POST',body:{activityId:a.activityId,opType}});ElMessage.success('操作成功');await load()}
function queryString(){const q=new URLSearchParams();if(filterId.value)q.set('activityId',filterId.value);if(range.value?.length){q.set('startTime',range.value[0]);q.set('endTime',range.value[1])}return q.toString()?'?'+q:''}
async function query(){const q=queryString();[stats.value,rows.value]=await Promise.all([api('/reg-stat'+q),api('/registration-data'+q)])}
onMounted(load)
</script>
<template>
  <div class="page-heading"><div><div class="eyebrow">ACTIVITY MANAGEMENT</div><h1>活动与报名</h1><p class="muted">发布活动、配置报名字段，集中查看全校正式报名数据。</p></div><el-button type="primary" @click="open(null)">＋ 新建活动</el-button></div>
  <div class="stats"><div class="stat"><small>报名总数</small><strong>{{stats.total}}</strong></div><div class="stat"><small>待审核</small><strong>{{stats.pending}}</strong></div><div class="stat"><small>已通过</small><strong>{{stats.approved}}</strong></div><div class="stat"><small>已驳回</small><strong>{{stats.rejected}}</strong></div></div>
  <el-tabs v-model="tab" class="section-tabs"><el-tab-pane label="我的活动" name="activities"/><el-tab-pane label="报名数据" name="data"/></el-tabs>
  <section v-if="tab==='activities'" class="surface"><div class="surface-title"><h3>我创建的活动</h3><el-button @click="load">刷新</el-button></div><el-table v-loading="loading" :data="activities" empty-text="点击右上角新建你的第一项活动"><el-table-column prop="title" label="活动名称" min-width="190"/><el-table-column prop="endTime" label="报名截止" width="175"/><el-table-column prop="reviewerName" label="审核教师" min-width="110"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.status==='1'?'success':row.status==='2'?'info':'warning'">{{activityNames[row.status]}}</el-tag></template></el-table-column><el-table-column label="操作" width="160"><template #default="{row}"><template v-if="row.status==='0'"><el-button link type="primary" @click="open(row)">编辑 / 发布</el-button><el-button link type="danger" @click="operate(row,'DELETE')">删除</el-button></template><el-button v-else-if="row.status==='1'" link type="warning" @click="operate(row,'OFFLINE')">下线</el-button><span v-else class="muted">已归档</span></template></el-table-column></el-table><p class="muted" style="margin:16px 0 0">发布后固定报名字段和审核教师，保留历史报名含义；后续可下线并新建活动。</p></section>
  <section v-else class="surface"><div class="surface-title"><h3>正式报名数据</h3><el-button type="primary" plain @click="download('/reg-export'+queryString(),'报名汇总.xlsx')">导出 Excel</el-button></div><div class="toolbar"><el-input-number v-model="filterId" :min="1" :controls="false" placeholder="活动编号（可空）" style="width:170px"/><el-date-picker v-model="range" type="datetimerange" value-format="YYYY-MM-DD HH:mm:ss" start-placeholder="提交开始时间" end-placeholder="提交结束时间" style="max-width:370px"/><el-button @click="query">筛选</el-button><el-button text @click="filterId=null;range=[];query()">清除</el-button></div><el-table :data="rows" empty-text="当前条件下暂无正式报名"><el-table-column prop="regId" label="编号" width="75"/><el-table-column prop="activityTitle" label="活动" min-width="180"/><el-table-column prop="studentName" label="学生" width="120"/><el-table-column prop="submitTime" label="提交时间" width="180"/><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="statusType(row.status)">{{registrationNames[row.status]}}</el-tag></template></el-table-column></el-table><p class="muted" style="margin-top:15px">页面展示最近200条；导出使用相同筛选条件，默认最多50000条。</p></section>
  <el-dialog v-model="opened" :title="draft.activityId?'编辑活动草稿':'新建校园活动'" width="820px" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="活动名称" required><el-input v-model="draft.title" maxlength="100" placeholder="例如：校园创新分享会"/></el-form-item><el-form-item label="活动介绍" required><el-input v-model="draft.content" type="textarea" :rows="3" maxlength="5000" placeholder="简要说明活动内容与报名要求"/></el-form-item><div style="display:grid;grid-template-columns:1fr 1fr;gap:18px"><el-form-item label="报名开始时间" required><el-date-picker v-model="draft.startTime" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="报名结束时间" required><el-date-picker v-model="draft.endTime" type="datetime" value-format="YYYY-MM-DD HH:mm:ss" style="width:100%"/></el-form-item></div><el-form-item label="审核教师（发布前必填）"><el-select v-model="draft.reviewerId" clearable placeholder="指定一位审核教师" style="width:100%"><el-option v-for="u in reviewers" :key="u.userId" :value="u.userId" :label="`${u.realName}（${u.userName}）`"/></el-select></el-form-item><el-divider content-position="left">报名表单字段</el-divider><p class="muted">字段标识使用字母开头，可含数字和下划线，不可重复。</p><div v-for="(f,index) in draft.fields" :key="index"><div class="form-builder-row"><el-input v-model="f.key" placeholder="字段标识"/><el-input v-model="f.label" placeholder="字段名称"/><el-select v-model="f.type"><el-option v-for="t in fieldTypes" :key="t.value" :label="t.label" :value="t.value"/></el-select><el-checkbox v-model="f.required">必填</el-checkbox><el-button text type="danger" @click="draft.fields.splice(index,1)">×</el-button></div><el-input v-if="f.type==='select'" v-model="f.optionsText" class="form-builder-options" placeholder="下拉选项，以逗号分隔，例如：大一，大二，大三，大四"/></div><el-button text type="primary" @click="addField">＋ 添加字段</el-button><el-form-item style="margin-top:16px"><el-checkbox v-model="draft.attachmentRequired">正式报名必须上传佐证材料</el-checkbox></el-form-item></el-form><template #footer><el-button @click="opened=false">取消</el-button><el-button :loading="busy" @click="save('SAVE_DRAFT')">保存草稿</el-button><el-button type="primary" :loading="busy" @click="save('PUBLISH')">发布活动</el-button></template></el-dialog>
</template>
